import { formatDelta, formatSize } from './size.js';

/** @typedef {import('./budget.js').RuleResult} RuleResult */
/** @typedef {import('./budget.js').Status} Status */

const ICON = { pass: '✔', warn: '!', fail: '✘' };
const EMOJI = { pass: '✅', warn: '⚠️', fail: '❌' };
const COLOR = { pass: 32, warn: 33, fail: 31 };

/**
 * @param {RuleResult} r
 */
function describe(r) {
  const what = r.kind === 'total' ? 'total' : 'largest file';
  return `${formatSize(r.size)} / ${formatSize(r.limit)} ${r.compression} (${what})`;
}

/**
 * @param {number | undefined} size
 * @param {number | undefined} baseline
 */
function delta(size, baseline) {
  return baseline === undefined || size === undefined ? '' : formatDelta(size - baseline);
}

/**
 * Renders a terminal report.
 * @param {{ results: RuleResult[], status: Status }} evaluation
 * @param {{ color?: boolean, verbose?: boolean }} [options]
 */
export function renderText({ results, status }, { color = false, verbose = false } = {}) {
  const paint = (/** @type {number} */ code, /** @type {string} */ s) => (color ? `\x1b[${code}m${s}\x1b[0m` : s);
  const lines = [paint(1, 'bundle-budget'), '─'.repeat(60)];
  for (const r of results) {
    const d = delta(r.size, r.baseline);
    lines.push(` ${paint(COLOR[r.status], ICON[r.status])} ${r.name.padEnd(22)} ${describe(r)}${d ? '  ' + paint(2, d) : ''}`);
    const offenders = r.kind === 'file' ? r.files.filter((f) => verbose || f.status !== 'pass') : verbose ? r.files : [];
    for (const f of offenders) {
      const fd = delta(f.size, f.baseline);
      lines.push(`     ${paint(COLOR[f.status], ICON[f.status])} ${f.path}  ${formatSize(f.size)}${fd ? '  ' + paint(2, fd) : ''}`);
    }
  }
  lines.push('─'.repeat(60));
  const summary = { pass: 'All budgets met.', warn: 'Budgets met, but some are close to their limit.', fail: 'Budget exceeded.' }[status];
  lines.push(paint(COLOR[status], `${ICON[status]} ${summary}`));
  return lines.join('\n');
}

/**
 * Renders a GitHub-flavored Markdown report, ready to post on a pull request.
 * @param {{ results: RuleResult[], status: Status }} evaluation
 */
export function renderMarkdown({ results, status }) {
  const title = { pass: 'All performance budgets met', warn: 'Performance budgets close to their limits', fail: 'Performance budget exceeded' }[status];
  const rows = results.map((r) => {
    const pct = r.limit ? Math.round((r.size / r.limit) * 100) : 0;
    return `| ${EMOJI[r.status]} | ${r.name} | ${r.kind === 'total' ? 'total' : 'per file'} · ${r.compression} | ${formatSize(r.size)} | ${formatSize(r.limit)} | ${pct}% | ${delta(r.size, r.baseline) || '—'} |`;
  });
  const failing = results.flatMap((r) => (r.kind === 'file' ? r.files.filter((f) => f.status === 'fail').map((f) => `- \`${f.path}\` — ${formatSize(f.size)} (limit ${formatSize(r.limit)})`) : []));
  return [
    `### ${EMOJI[status]} ${title}`,
    '',
    '| | Budget | Measured | Size | Limit | Used | Δ vs baseline |',
    '| :-: | :-- | :-- | --: | --: | --: | --: |',
    ...rows,
    ...(failing.length ? ['', '**Files over budget**', '', ...failing] : []),
    '',
    '<sub>Generated by bundle-budget</sub>',
  ].join('\n');
}
